-- ============================================================================
--  Acto — 5 coachings importes depuis Google Drive (dossier IMPRO)
--  A passer dans l'editeur SQL Supabase (projet gssotstyevehbzydzhlq).
--  Re-executable : un coaching deja present sur le compte (meme titre) n'est
--  pas recree.
-- ============================================================================
--
--  Chaque Google Doc devient un coaching sur TON COMPTE : dans le Studio,
--  Coaching -> Mes coachings -> « Sur mon compte » -> Recuperer.
--
--  Le compte est retrouve par e-mail. Laisser v_email vide ne marche que s'il
--  n'existe qu'un seul compte administrateur.
-- ============================================================================

do $seed$
declare
  v_email text := '';          -- <- ton e-mail de connexion Acto (ou vide : l'unique compte admin)
  v_owner uuid;
  v_admins int;
  v_ajouts int := 0;
begin
  if btrim(v_email) <> '' then
    select u.id into v_owner from auth.users u where lower(u.email) = lower(btrim(v_email));
    if v_owner is null then raise exception 'Aucun compte Acto avec l''e-mail %', v_email; end if;
  else
    select count(*) into v_admins from public.profiles where is_admin;
    if v_admins <> 1 then raise exception '% comptes admin : renseigne v_email en haut du fichier', v_admins; end if;
    select id into v_owner from public.profiles where is_admin;
  end if;

  insert into public.shared_resources (owner_id, resource_type, title, data, updated_by)
  select v_owner, 'entrainement', x.title, x.data, v_owner
    from (values
      -- 1. Coaching S1 du 07/09/2026 - Laugh - Premiere approche de l'improvisation (5 blocs)
      ('Coaching S1 du 07/09/2026 - Laugh - Première approche de l''improvisation', $json${"id":"92135061-ab08-4bd2-b82e-7784cd111557","kind":"training","title":"Coaching S1 du 07/09/2026 - Laugh - Première approche de l'improvisation","locale":"fr","level":"debutant","createdAt":1789643736945,"updatedAt":1789643736945,"scoring":false,"showScores":false,"filming":false,"display":{"cointoss":"ask"},"teams":[],"meta":{"nbWarmups":2,"nbExercises":3},"targetSec":6600,"participants":[],"setlist":[{"id":"bc529ac8-e297-4e6f-af74-826df918b2f7","type":"warmup","status":"planned","durationSec":480,"locks":{},"recordedFiles":[],"warmup":{"name":"Accueil et cadrage","desc":"Cadre : 17h00–18h50 (1h50) · 2 coachs (Kevin - lead / Seb - support) · 7 jouteurs (2 F / 5 M), 6 participants de 16 à 30 ans, débutants complets · Projet Erasmus+. Présentation rapide de l'improvisation, du déroulement du coaching et des objectifs du projet Erasmus. Fil rouge : les règles du match, les refus et les fautes de jeu ne sont pas exposés en bloc au début ; ils sont expliqués au fil des exercices, au moment où la situation les fait apparaître. Objectifs de la séance : faire découvrir le format du match d'improvisation (règles, fautes, refus de jeu) ; installer les fondamentaux du jeu collectif (conscience du groupe, de l'espace scénique et du public) ; faire vivre concrètement l'acceptation de la proposition (« oui, et… ») ; créer un climat de confiance et lever l'appréhension du passage sur scène. Points de vigilance : repérer qui refuse les propositions (blocages, négations) pour y revenir en débrief ; garder un débrief court, concret et valorisant ; équilibrer le temps de passage entre les 7 jouteurs.","duration_seconds":null,"wtype":"Accueil"}},{"id":"c5d3d60a-03ef-4e7d-afe4-8c876214a393","type":"warmup","status":"planned","durationSec":180,"locks":{},"recordedFiles":[],"warmup":{"name":"Déplacement évolutif","desc":"Marche libre dans l'espace, tout le groupe. 1) Marcher en prenant en compte l'autre, la scène et la position du public. 2) Accélération progressive, puis retour au ralenti, puis vitesse normale. 3) Passation d'un stylo : on le donne en disant son propre prénom. 4) Variante : on le donne en disant soit le prénom de l'autre, soit un prénom inventé. Objectifs : mise en corps, écoute périphérique, mémorisation des prénoms, premier lâcher-prise.","duration_seconds":null,"wtype":"Échauffement"}},{"id":"f7f9d9c6-3dd7-4e94-abb8-d54bbde86529","type":"exercise","status":"planned","durationSec":1560,"locks":{},"recordedFiles":[],"exercise":{"name":"Cercle — l'objet transformé","desc":"En cercle, on se donne le crayon, mais ce n'est plus un crayon. 1) Passation sans geste ni émotion (neutre). 2) Passation avec geste et émotion. 3) Ajout de la réaction de celui qui reçoit. 4) Décrochage verbal : l'un mime une action avec le stylo, l'autre dit quelque chose qui n'a rien à voir, et le premier répond en acceptant la proposition et en lui donnant du sens. Objectifs : mime et détournement d'objet, engagement émotionnel, et surtout acceptation : on ne bloque pas la proposition de l'autre, on la justifie."}},{"id":"3725c10e-0754-4f73-a86e-ea6bb3e62603","type":"exercise","status":"planned","durationSec":1560,"locks":{},"recordedFiles":[],"exercise":{"name":"Mitraillette","desc":"Les jouteurs sont en file indienne. Un jouteur se place face à la file et lance une phrase, qu'il répète à chacun. Chaque jouteur s'avance à son tour, répond, reçoit une réplique en retour, puis cède la place au suivant. Une fois la file passée, un nouveau meneur prend la place avec une nouvelle phrase. Objectifs : réactivité, spontanéité, désinhibition ; on répond sans réfléchir, sans chercher la « bonne » réponse."}},{"id":"eb252b76-7a0a-49e2-9b3e-7801b987aee4","type":"exercise","status":"planned","durationSec":1560,"locks":{},"recordedFiles":[],"exercise":{"name":"Impro 1 contre 1 — 30 secondes","desc":"Improvisations libres à deux, format court (30 s), avec débrief immédiat après chaque passage. Objectifs : premier passage sur scène en conditions de match et mise en application directe de ce qui a été travaillé. Le format très court sécurise les débutants."}}],"cursor":0,"journal":[],"matchDate":"2026-09-07"}$json$::jsonb),
      -- 2. Coaching S2 du 14/09/2026 - Laugh - Quel improvisateur etes-vous ? (15 blocs)
      ('Coaching S2 du 14/09/2026 - Laugh - Quel improvisateur êtes-vous ?', $json${"id":"ea8acfe1-4da9-490a-9d84-820039c63ca6","kind":"training","title":"Coaching S2 du 14/09/2026 - Laugh - Quel improvisateur êtes-vous ?","locale":"fr","level":"debutant","createdAt":1789643736945,"updatedAt":1789643736945,"scoring":false,"showScores":false,"filming":false,"display":{"cointoss":"ask"},"teams":[],"meta":{"nbWarmups":6,"nbExercises":9},"targetSec":5100,"participants":[{"name":"Yann","user_id":null},{"name":"Gabriel","user_id":null},{"name":"Quentin","user_id":null},{"name":"Louise","user_id":null}],"setlist":[{"id":"a07d1d3e-bf38-4ad6-a995-7b89bdb450b1","type":"warmup","status":"planned","durationSec":180,"locks":{},"recordedFiles":[],"warmup":{"name":"Accueil et portrait chinois","desc":"Cadre : lundi 14 septembre 2026, 17h20–18h45 (1h25) · La Condition Publique · Team Laugh (nom provisoire) · 2 coachs (Cath / Seb) · Projet Erasmus. Chaque jouteur cherche qui il incarnerait s'il était un animal (animal totem), un élément (eau, air, feu, terre), un vêtement, un plat, un véhicule. Fil rouge : ce portrait chinois revient dans les exercices 9, 12, 13 et 14 ; chacun garde ses réponses en tête pour toute la séance. Objectifs : poser la matière personnelle incarnée tout au long du coaching et amorcer la question « quel improvisateur suis-je ? » (émotions, mimes, narration). Objectifs de la séance : identifier son propre registre de jeu ; élargir la palette émotionnelle et tenir une émotion dans la durée ; travailler l'incarnation par le corps (point moteur, animal totem, élément naturel) ; renforcer l'écoute collective et la mémoire du groupe ; gagner en endurance de parole et en ancrage. Points de vigilance : séance dense (14 exercices en 1h25, environ 5 min chacun) : enchaîner vite, consignes très courtes, peu de débriefs intermédiaires ; groupe de 4 : attention à la fatigue et à la répétition ; sur les émotions (6, 7, 8), repérer qui se réfugie dans le rire ou dans une seule couleur émotionnelle ; sur le vomi de paroles, noter les mouvements parasites de chacun ; sur les incarnations (9, 12, 13, 14), chercher l'incarnation plutôt que l'imitation ; garder le lien avec le portrait chinois explicite à chaque retour.","duration_seconds":null,"wtype":"Accueil"}},{"id":"84430562-9aba-43fc-8b5e-fe3be544338f","type":"warmup","status":"planned","durationSec":180,"locks":{},"recordedFiles":[],"warmup":{"name":"Frottement et boule d'émotion négative","desc":"Chacun se frotte de la tête aux pieds, rassemble ce qu'il récolte en une boule d'émotion négative et la lance au milieu du cercle. Objectifs : mise en corps, évacuation de la journée, entrée collective dans l'espace de jeu.","duration_seconds":null,"wtype":"Échauffement"}},{"id":"b7a393cd-2cb6-419f-b92c-b958c6e46ef5","type":"warmup","status":"planned","durationSec":180,"locks":{},"recordedFiles":[],"warmup":{"name":"Marche et point moteur","desc":"Marche libre dans l'espace. Le coach fait changer le point moteur : la zone du corps qui donne l'impulsion, le point de force et d'appui (nez, poitrine, genou, ventre, pied…). Objectifs : sentir comment une simple modification corporelle change tout le personnage, sortir de sa démarche habituelle.","duration_seconds":null,"wtype":"Échauffement"}},{"id":"129c452c-44ee-4e72-8a3d-a503aee70fdf","type":"warmup","status":"planned","durationSec":180,"locks":{},"recordedFiles":[],"warmup":{"name":"Échange de prénoms","desc":"En marchant dans l'espace, chacun se donne un prénom et l'échange à chaque rencontre. Dès que quelqu'un nous redonne notre propre prénom, on va s'asseoir. Objectifs : mémorisation, attention à l'autre, concentration dans la durée.","duration_seconds":null,"wtype":"Échauffement"}},{"id":"e6b54fd3-a61d-4599-8cb7-852922fb244e","type":"warmup","status":"planned","durationSec":180,"locks":{},"recordedFiles":[],"warmup":{"name":"Échange de prénoms + métier","desc":"Évolution de l'échange de prénoms : on ajoute un métier au prénom. Il faut que les deux soient redonnés correctement pour aller s'asseoir. Objectifs : charge mémorielle accrue, précision de l'écoute, coopération pour que tout le groupe finisse assis.","duration_seconds":null,"wtype":"Échauffement"}},{"id":"e57916e1-4799-4e06-800e-8c280ad23c4e","type":"warmup","status":"planned","durationSec":180,"locks":{},"recordedFiles":[],"warmup":{"name":"Auto-comptage","desc":"En marchant dans l'espace, le groupe compte de 1 à 10 puis de 10 à 1. Chacun dit un chiffre aléatoirement. Si deux jouteurs parlent en même temps, on repart à 1. Objectifs : écoute fine du groupe, gestion du silence, savoir prendre la parole et savoir la laisser.","duration_seconds":null,"wtype":"Échauffement"}},{"id":"59312ceb-a0eb-4a1a-8b73-cab7bcd19bb8","type":"exercise","status":"planned","durationSec":180,"locks":{},"recordedFiles":[],"exercise":{"name":"Cercle — prénom, geste et émotion","desc":"En cercle, chacun dit son prénom en y associant un geste et une émotion. Les autres répondent « Bonjour [prénom] » avec la même énergie, la même émotion et la même gestuelle. Objectifs : engagement émotionnel assumé devant le groupe, reproduction fidèle de la proposition de l'autre, mise en énergie collective."}},{"id":"84a894c4-5eb5-4806-a9f6-5565391f81e7","type":"exercise","status":"planned","durationSec":180,"locks":{},"recordedFiles":[],"exercise":{"name":"Cercle — tenir l'émotion dans le regard","desc":"En cercle, le coach donne une émotion. Chacun lève la tête et regarde les autres en gardant son émotion : haine, rage, colère, tristesse, timidité, joie, amour… Si on rit et qu'on perd l'émotion, on baisse la tête. Objectifs : tenir une émotion au contact du regard de l'autre, résister au rire de gêne, explorer les émotions inconfortables."}},{"id":"daca2ee6-e8c9-4931-bd20-d1d1526fe5c6","type":"exercise","status":"planned","durationSec":180,"locks":{},"recordedFiles":[],"exercise":{"name":"1, 2, 3 soleil des émotions","desc":"Principe du 1, 2, 3 soleil, avec une émotion qui doit monter graduellement à chaque arrêt. Objectifs : travailler la gradation émotionnelle plutôt que le tout ou rien, gérer la montée en intensité par paliers."}},{"id":"ff8f43a5-2bdd-4f8c-a73b-cf14e1a4b17d","type":"exercise","status":"planned","durationSec":180,"locks":{},"recordedFiles":[],"exercise":{"name":"Le café des animaux totems","desc":"Chacun incarne l'attitude humaine qu'aurait son animal totem (un humain qui serait un chat, par exemple) dans ses réponses et sa gestuelle. On entre dans un café, le coach vient servir à boire. À chaque jouteur de faire comprendre aux autres quel est son animal. Objectifs : transposer l'animal en comportement humain plutôt qu'en imitation, tenir un personnage dans une situation banale, jouer la subtilité sans surjouer."}},{"id":"49896af3-8905-41e5-a7f5-a8b4a1f936dd","type":"exercise","status":"planned","durationSec":180,"locks":{},"recordedFiles":[],"exercise":{"name":"Impro solo — l'envie contrariée","desc":"Seul en scène, montrer et jouer le fait qu'on a envie de manger quelque chose, mais un événement empêche de le manger. Objectifs : construire un désir clair puis un obstacle, faire vivre une situation seul et sans parole, précision du mime."}},{"id":"976434f3-6be3-4d8c-ab7a-32b2e23cdf14","type":"exercise","status":"planned","durationSec":180,"locks":{},"recordedFiles":[],"exercise":{"name":"Vomi de paroles","desc":"Tenir sur un sujet donné sans s'arrêter de parler, en durées croissantes selon l'aisance du jouteur : 10 secondes, 30 secondes, 1 minute. Attention : éviter les mouvements parasites et rester ancré sur place. Objectifs : endurance de parole, lutte contre le blanc, ancrage corporel et repérage des tics de nervosité."}},{"id":"c3b05237-6e6c-4e30-85c5-ed464ca82829","type":"exercise","status":"planned","durationSec":180,"locks":{},"recordedFiles":[],"exercise":{"name":"Mime, émotion et réaction de l'animal totem","desc":"Le coach demande au jouteur qui il est. Celui-ci répond en nommant son animal, tout en jouant l'incarnation de cet animal : gestuelle, émotion, réaction. Objectifs : faire coïncider le corps et la parole, engager tout le corps dans une réponse simple."}},{"id":"1b7a84fd-aee2-418c-a045-ccf7d096f464","type":"exercise","status":"planned","durationSec":180,"locks":{},"recordedFiles":[],"exercise":{"name":"Incarner son élément naturel","desc":"Mime et émotion de l'élément naturel que l'on incarne : eau, air, feu, terre. La terre est ancrée au sol et prend de la place ; l'air bouge et reste léger dans ses déplacements… Objectifs : traduire une qualité abstraite en qualité de mouvement, faire varier son rapport au sol, à l'espace et au rythme."}},{"id":"f11c1683-0138-4167-911f-282179c14d44","type":"exercise","status":"planned","durationSec":180,"locks":{},"recordedFiles":[],"exercise":{"name":"Animal + moyen de transport","desc":"Mime d'un animal se déplaçant sur un moyen de transport, par exemple un flamant rose sur une trottinette qui n'avance pas. Objectifs : croiser deux éléments du portrait chinois, tenir deux contraintes corporelles à la fois, faire naître le comique de la situation plutôt que de le chercher."}}],"cursor":0,"journal":[],"matchDate":"2026-09-14"}$json$::jsonb),
      -- 3. Coaching S1 du 02/09/2026 - Les QI cuits - Inspiration musicale / Personnage / Lien / Lieu (6 blocs)
      ('Coaching S1 du 02/09/2026 - Les QI cuits - Inspiration musicale / Personnage / Lien / Lieu', $json${"id":"26f2a26f-df69-47f7-906d-50e32dc0b6d8","kind":"training","title":"Coaching S1 du 02/09/2026 - Les QI cuits - Inspiration musicale / Personnage / Lien / Lieu","locale":"fr","level":"debutant","createdAt":1789643736945,"updatedAt":1789643736945,"scoring":false,"showScores":false,"filming":false,"display":{"cointoss":"ask"},"teams":[],"meta":{"nbWarmups":1,"nbExercises":5},"targetSec":7200,"participants":[],"setlist":[{"id":"1bad829c-8097-4889-99b7-40aec2451f59","type":"warmup","status":"planned","durationSec":480,"locks":{},"recordedFiles":[],"warmup":{"name":"Accueil et cadrage","desc":"Cadre : 02/09/2026, 19h–21h · Team Les QI cuits · Coach : Sophie · Matériel : enceinte et sélection musicale, le coach gère les montées et descentes de son. Présentation du thème et du dispositif : le groupe est assis, la musique tourne, personne n'est désigné, on monte quand on se sent inspiré. Fil rouge : les quatre parties forment une progression (personnage seul, puis lien, puis lieu, puis titre imposé) ; ne pas les mélanger ni passer à la suivante tant que la précédente n'est pas acquise. Objectifs de la séance : utiliser la musique comme déclencheur d'inspiration ; construire un personnage par le corps et le visage à partir d'une posture figée ; offrir de la matière à son partenaire sans l'enfermer ; distinguer le factuel, le lien et la scénarisation, dans cet ordre ; travailler la manipulation d'objets et la création de lieu sans parole ; oser monter sur scène sans savoir où l'on va. Points de vigilance : gérer les niveaux de musique ; rappeler la distinction entre marche neutre (parties 1 et 2) et déambulation libre (parties 3 et 4) ; garder des présentations courtes et ouvertes ; en partie 2, couper la scénarisation dès qu'elle apparaît ; laisser le silence faire son travail, ne pas désigner qui monte ; observer qui monte en premier et qui ne monte jamais.","duration_seconds":null,"wtype":"Accueil"}},{"id":"83fbce97-e4ba-466a-98f2-fcd2481b066c","type":"exercise","status":"planned","durationSec":1050,"locks":{},"recordedFiles":[],"exercise":{"name":"Partie 1 — la posture et le monologue","desc":"1) Le groupe écoute une vingtaine de secondes de musique. Celui qui se sent inspiré se lève, marche de façon neutre jusqu'à sa place, prend une posture (corps et visage) et se fige. 2) Les autres observent ; celui qui se sent inspiré le rejoint pendant que le coach baisse la musique, et le présente calmement au public pendant environ 30 secondes (« voici… aujourd'hui est un jour important pour… car… ») : assez de matière, pas trop de détails. Il s'éclipse ensuite discrètement. 3) Le personnage principal s'anime et démarre un monologue d'une à deux minutes ; c'est lui qui fait comprendre quand c'est terminé. Objectifs : se laisser inspirer par la musique, construire un personnage par le corps avant les mots, offrir de la matière sans enfermer le partenaire, tenir seul en scène."}},{"id":"3cd12121-d499-4130-8175-4577bce53bdb","type":"exercise","status":"planned","durationSec":1050,"locks":{},"recordedFiles":[],"exercise":{"name":"Variante 1B — la présentation en miroir (non testée)","desc":"Même départ qu'en partie 1 : une personne monte, prend une posture et se fige ; une deuxième vient la présenter au public, puis se fige à son tour. Le premier personnage se dégèle lentement, observe quelques secondes le deuxième, se tourne vers le public et le présente à son tour en faisant comprendre les liens qui les unissent. Quand il le touche (l'épaule, la main), l'impro entre eux commence. Exercice non encore testé : à placer en fin de partie 1 si le groupe est à l'aise. Objectifs : inverser le rapport présentant / présenté, faire naître le lien depuis le personnage lui-même, utiliser le contact comme signal de départ."}},{"id":"ab50b424-8ca5-40ce-b429-069215598da3","type":"exercise","status":"planned","durationSec":1050,"locks":{},"recordedFiles":[],"exercise":{"name":"Partie 2 — le factuel puis le lien","desc":"1) Celui qui est inspiré se lève, marche de façon neutre, prend une posture et un visage. 2) Une deuxième personne vient à côté ; la musique baisse ; elle présente la personne au public en 4 ou 5 phrases factuelles, sans se situer par rapport à elle ni parler du lien qui les unit. 3) Elle se fige à son tour ; le coach remet un peu de musique. 4) Une troisième personne parle de la deuxième et des liens qu'elle entretient avec la première, puis s'éclipse et l'impro commence. Exemple factuel : « Anne est une vendeuse de pommes. Chaque semaine, elle vient sur la place du marché… » Exemple de lien : « Je vous présente Jacques… si Jacques vient au marché, c'est surtout pour voir Anne, la vendeuse de pommes, dont il est secrètement amoureux… » Objectifs : séparer le factuel du relationnel, résister à la tentation de tout écrire d'avance, faire émerger une situation à partir de deux portraits posés l'un après l'autre."}},{"id":"d0b4cdf9-a05a-41b2-b9f9-0e36809e31f8","type":"exercise","status":"planned","durationSec":1050,"locks":{},"recordedFiles":[],"exercise":{"name":"Partie 3 — planter le lieu","desc":"On écoute la musique, mais la personne qui monte ne doit surtout pas être neutre : elle peut se faire plaisir, déambuler, se dandiner, utiliser tout l'espace. Elle fait quelques manipulations pour préciser le lieu (un salon de coiffure, par exemple). Dès que c'est clair, deux ou trois personnes la rejoignent et complètent les manipulations pour faire vivre ce lieu. Le coach baisse la musique et l'impro commence. Objectifs : passer du personnage au lieu, précision de la manipulation d'objets, lecture de la proposition de l'autre avant de la compléter, occupation de l'espace."}},{"id":"80db0858-8309-4291-8c4b-6f9a9c222c62","type":"exercise","status":"planned","durationSec":1050,"locks":{},"recordedFiles":[],"exercise":{"name":"Partie 4 — mode laboratoire : le titre imposé","desc":"Comme la partie 3, mais un jouteur se place dos à la scène dès le début. Une première personne crée un lieu (une boulangerie, une gare…) ; quand c'est clair, on vient l'habiter à trois ou quatre, sans parler. La musique baisse ; la personne de dos se retourne et annonce « Le titre de l'impro sera… ». Le titre n'aura sans doute rien à voir : les jouteurs doivent utiliser malgré tout les décors posés. Conseil : celui qui est de dos garde un deuxième titre de réserve s'il tombe juste sur le lieu planté. Objectifs : accepter une contrainte imposée en cours de route, justifier l'écart entre le décor et le titre, jouer avec ce qui est déjà là plutôt que de repartir de zéro."}}],"cursor":0,"journal":[],"matchDate":"2026-09-02"}$json$::jsonb),
      -- 4. Coaching S2 du 09/09/2026 - Les QI cuits - Confiance en l'autre / Contact / Ecoute (8 blocs)
      ('Coaching S2 du 09/09/2026 - Les QI cuits - Confiance en l''autre / Contact / Ecoute', $json${"id":"7b381c52-1d7e-4804-b9ca-6b8a301d70d8","kind":"training","title":"Coaching S2 du 09/09/2026 - Les QI cuits - Confiance en l'autre / Contact / Ecoute","locale":"fr","level":"debutant","createdAt":1789643736945,"updatedAt":1789643736945,"scoring":false,"showScores":false,"filming":false,"display":{"cointoss":"ask"},"teams":[],"meta":{"nbWarmups":7,"nbExercises":1},"targetSec":7200,"participants":[{"name":"Sam","user_id":null},{"name":"Kev","user_id":null},{"name":"Kevvdb","user_id":null},{"name":"Sophie","user_id":null},{"name":"Heloise","user_id":null},{"name":"Marc","user_id":null},{"name":"Lucie","user_id":null},{"name":"Vero","user_id":null},{"name":"Sébastien","user_id":null},{"name":"Favid","user_id":null}],"setlist":[{"id":"98c5ec75-a45e-45aa-9baf-2bfcc44d98ec","type":"warmup","status":"planned","durationSec":480,"locks":{},"recordedFiles":[],"warmup":{"name":"Accueil et cadrage","desc":"Cadre : mercredi 9 septembre 2026, 19h00–21h00 · Team Les QI cuits · Coach : Jonathan. Présentation du thème. Rappel du cadre autour du toucher : chacun peut signaler une limite à tout moment, le contact reste respectueux et on prend soin de son partenaire. Fil rouge : tous les exercices d'échauffement préparent l'impro finale en catégorie contact ; le toucher et l'écoute doivent devenir des outils de jeu sur scène. Objectifs de la séance : développer la confiance en l'autre par le contact physique, dans un cadre sécurisé ; renforcer l'écoute sous toutes ses formes (partenaire, groupe, sans le regard) ; travailler la synchronisation et la conscience collective sans leader ; réinvestir ces acquis dans une impro en catégorie contact. Points de vigilance : respecter les limites de chacun sur le toucher et proposer une alternative plutôt que forcer ; sécuriser l'espace pour les exercices à l'aveugle ; sur la baudruche, chute lente et contrôlée, groupe en place avant de lâcher ; au débrief, faire le lien avec l'échauffement ; équilibrer le temps de passage.","duration_seconds":null,"wtype":"Accueil"}},{"id":"2cd8ab73-6be1-494f-9ce6-f4637f7a6d2d","type":"warmup","status":"planned","durationSec":480,"locks":{},"recordedFiles":[],"warmup":{"name":"Guider à l'aveugle","desc":"En binôme, l'un a les yeux bandés avec un foulard. 1) Le guide fait avancer l'aveugle en le tenant par la main. 2) Le guide lâche la main et guide uniquement à la voix. 3) Le guide fait vivre une aventure à l'aveugle en la racontant ; l'aveugle mime les actions au fur et à mesure. Inversion des rôles au bout de 5 minutes. Objectifs : lâcher le contrôle et s'en remettre à l'autre, responsabilité du guide, passage progressif du toucher à la voix, engagement corporel dans le mime.","duration_seconds":null,"wtype":"Échauffement"}},{"id":"a540d0f5-4a9c-4e07-a0a2-2e45e8331b24","type":"warmup","status":"planned","durationSec":180,"locks":{},"recordedFiles":[],"warmup":{"name":"Retrouver le poussin à l'aveugle","desc":"Les jouteurs se déplacent ensemble en faisant des bruits d'animaux de la ferme. Deux jouteurs ont les yeux bandés et font le bruit du poussin : ils doivent se retrouver en se déplaçant au milieu du groupe. On change de binôme à chaque tour. Objectifs : écoute sélective (isoler un son dans le brouhaha), orientation dans l'espace sans la vue, lâcher-prise par le jeu vocal.","duration_seconds":null,"wtype":"Échauffement"}},{"id":"da48bab3-3065-4c8a-9df9-8b1c3cc2bec2","type":"warmup","status":"planned","durationSec":330,"locks":{},"recordedFiles":[],"warmup":{"name":"Baudruche","desc":"Les jouteurs se déplacent librement. Quand le coach annonce un prénom, ce jouteur se dégonfle comme une baudruche et se laisse tomber tout doucement. Les autres vont le soutenir, puis le relever après un certain temps. Objectifs : confiance dans le groupe (je peux tomber, on me rattrape), vigilance collective, réactivité à l'appel.","duration_seconds":null,"wtype":"Échauffement"}},{"id":"89479f20-10bc-4580-9a37-74353be7e3f3","type":"warmup","status":"planned","durationSec":480,"locks":{},"recordedFiles":[],"warmup":{"name":"Actions synchronisées au top du coach","desc":"Les jouteurs marchent dans l'espace. Au signal du coach : 1 clap, on saute tous ensemble ; 2 claps, on s'agenouille ; 3 claps, on tourne sur soi-même ; 4 claps, on s'arrête, on compte 1, 2, 3, puis on repart tous ensemble. Objectifs : écoute du signal, synchronisation du groupe, sentir le groupe pour repartir ensemble sans que personne ne mène.","duration_seconds":null,"wtype":"Échauffement"}},{"id":"8847c2a3-8609-45ec-8b3e-9cf3a79ecded","type":"warmup","status":"planned","durationSec":180,"locks":{},"recordedFiles":[],"warmup":{"name":"Auto-comptage","desc":"Sans attribuer de chiffre, le groupe compte de 1 à 10, puis de 10 à 1. Chaque jouteur peut dire un chiffre à tout moment. Dès que deux jouteurs parlent en même temps, on recommence. Les jouteurs ne gardent pas le même chiffre d'un essai à l'autre. Objectifs : écoute fine du groupe, gestion du silence, savoir prendre la parole et savoir la laisser.","duration_seconds":null,"wtype":"Échauffement"}},{"id":"6fdfd8aa-b500-4788-ac62-f1547e62bfde","type":"warmup","status":"planned","durationSec":180,"locks":{},"recordedFiles":[],"warmup":{"name":"Échange de prénoms","desc":"Chaque jouteur s'invente un prénom. Les jouteurs marchent et s'échangent les prénoms qu'ils portent. Dès qu'un jouteur récupère son propre prénom inventé, il va s'asseoir. L'exercice est réussi quand tout le monde est assis. Variante : on associe un métier au prénom ; il faut récupérer les deux pour aller s'asseoir. Objectifs : mémorisation, attention à l'autre, concentration dans la durée, coopération pour que tout le groupe réussisse.","duration_seconds":null,"wtype":"Échauffement"}},{"id":"484ebfd3-5baf-407c-9868-d49d13a77b3b","type":"exercise","status":"planned","durationSec":3210,"locks":{},"recordedFiles":[],"exercise":{"name":"Impro catégorie contact — 3 min, 3 jouteurs","desc":"Improvisations en catégorie contact : les jouteurs ne peuvent parler que lorsqu'ils sont en contact physique avec un partenaire (règle à préciser en début d'exercice). Format de 3 minutes à 3 jouteurs, avec débrief court après chaque passage. Objectifs : réinvestir la confiance et l'écoute travaillées à l'échauffement, utiliser le contact comme moteur de jeu et non comme contrainte, gérer une scène à trois."}}],"cursor":0,"journal":[],"matchDate":"2026-09-09"}$json$::jsonb),
      -- 5. Coaching S3 du 16/09/2026 - Les QI cuits - Apporter plus qu'un bonjour (9 blocs)
      ('Coaching S3 du 16/09/2026 - Les QI cuits - Apporter plus qu''un bonjour', $json${"id":"900dd2e1-332e-41b9-b760-9476a6958524","kind":"training","title":"Coaching S3 du 16/09/2026 - Les QI cuits - Apporter plus qu'un bonjour","locale":"fr","level":"debutant","createdAt":1789643736945,"updatedAt":1789643736945,"scoring":false,"showScores":false,"filming":false,"display":{"cointoss":"ask"},"teams":[],"meta":{"nbWarmups":4,"nbExercises":5},"targetSec":7200,"participants":[{"name":"David","user_id":null},{"name":"Vero","user_id":null},{"name":"Vero","user_id":null},{"name":"Sophie","user_id":null},{"name":"Tanguy","user_id":null},{"name":"Kevin VDB","user_id":null},{"name":"Lucie","user_id":null},{"name":"Seb","user_id":null},{"name":"V (à vérifier)","user_id":null}],"setlist":[{"id":"ed623ce7-566b-479b-97e1-85a7e488c2af","type":"warmup","status":"planned","durationSec":480,"locks":{},"recordedFiles":[],"warmup":{"name":"Accueil et cadrage","desc":"Cadre : mercredi 16 septembre 2026, 19h–21h · La Grange / La prairie · Team Les QI cuits · Coach : Jonathan. Thème : comment apporter plus qu'un bonjour ou amener plus qu'une question ? Fil rouge : on entend souvent qu'il ne faut « ni dire bonjour ni poser de question » en impro. La séance prend le problème à l'envers : on garde le bonjour et la question, mais on les charge de contexte, d'émotion et de relation. Les exercices montent en exigence, du simple bonjour jusqu'à la question qui lance une scène entière. Objectifs de la séance : amener le plus vite possible du contexte, de l'émotion et une relation ; déconstruire l'idée qu'on ne pourrait ni dire bonjour ni poser une question ; faire de la question un outil de proposition ; articuler décor et démarrage de scène ; réinvestir le tout en conditions de match sur des impros mixtes à deux. Points de vigilance : repérer les questions creuses (« ça va ? », « qu'est-ce que tu fais ? ») et les faire reformuler ; message positif : on ajoute plutôt qu'on interdit ; attention à la surcharge inverse (trois informations dans une question enferment le partenaire) ; prévoir la rotation des exercices décor + question pour que chacun passe dans les deux rôles ; débriefs très courts ; sur la simulation finale, observer combien de temps il faut pour que la relation soit posée.","duration_seconds":null,"wtype":"Accueil"}},{"id":"df82b02a-0801-492b-a0a6-ad9dd3d8e3a4","type":"warmup","status":"planned","durationSec":180,"locks":{},"recordedFiles":[],"warmup":{"name":"Marche étirée puis déconstruite","desc":"Marche dans l'espace en s'étirant au fur et à mesure, pour finir par marcher de la façon la plus déconstruite possible. Objectifs : réveil corporel, sortie de la démarche quotidienne, premier lâcher-prise avant de parler.","duration_seconds":null,"wtype":"Échauffement"}},{"id":"982874ed-8b7b-42c7-98e7-d691b356d953","type":"warmup","status":"planned","durationSec":180,"locks":{},"recordedFiles":[],"warmup":{"name":"Le bonjour chargé","desc":"On continue à marcher et on se dit bonjour, mais en amenant une émotion ou un contexte, par exemple « Enchanté, cher voisin ». Objectifs : cœur du thème, montrer qu'un bonjour peut à lui seul poser une relation, un lieu ou une humeur. Premier réflexe à installer : ne jamais dire une réplique « à vide ».","duration_seconds":null,"wtype":"Échauffement"}},{"id":"0e39e97e-4e33-4750-9ec5-4578bb5f8ba1","type":"warmup","status":"planned","durationSec":180,"locks":{},"recordedFiles":[],"warmup":{"name":"Cercle — la chaîne des regards","desc":"Le groupe est en rond. Le coach lance un regard vers une personne ; dès qu'il a capté son regard, il avance vers elle. Celle-ci doit à son tour capter le regard d'un autre et avancer vers lui pour libérer sa place. Le coach lance ensuite un deuxième regard : il y a alors en permanence deux personnes qui avancent et deux qui cherchent un regard. Objectifs : connexion silencieuse avant la parole, vigilance périphérique, gérer deux flux en même temps sans paniquer.","duration_seconds":null,"wtype":"Échauffement"}},{"id":"6009cffd-e657-4556-a922-eed0f65c387e","type":"exercise","status":"planned","durationSec":870,"locks":{},"recordedFiles":[],"exercise":{"name":"Ceci n'est pas ma main","desc":"En file indienne, les jouteurs avancent tour à tour devant le coach et enchaînent des phrases et des gestes commençant tous par « Ceci n'est pas ma main, ceci est… », en mimant ce que c'est. Objectifs : détournement d'objet, spontanéité, synchronisation du dire et du montrer : on ne décrit pas, on incarne."}},{"id":"86ae2f19-3b92-42eb-9e9b-10280761f7d5","type":"exercise","status":"planned","durationSec":870,"locks":{},"recordedFiles":[],"exercise":{"name":"Goalkeeper — la question à contexte","desc":"Une personne est seule face aux autres, en file indienne. Chacun leur tour, les jouteurs avancent et posent une question qui donne immédiatement un contexte à l'impro ; l'autre répond. Exemple : « Comment est-ce que t'as réussi à mettre tous tes vêtements à l'envers ? » Objectifs : transformer la question en proposition (elle apporte de la matière au lieu d'en réclamer), réactivité, cadence soutenue pour éviter de réfléchir."}},{"id":"eac929a9-590a-4410-be7a-3df28177b6c2","type":"exercise","status":"planned","durationSec":870,"locks":{},"recordedFiles":[],"exercise":{"name":"Décor puis question — celui qui plante demande","desc":"Un jouteur monte sur scène et installe un décor. Une fois le décor installé, un deuxième jouteur monte ; c'est le premier qui lui pose une question à contexte pour démarrer une impro courte d'environ une minute (à l'appréciation du coach). On tourne : chacun passe du rôle de planteur de décor à celui de jouteur qui entre. Objectifs : faire servir le décor au démarrage de la scène, poser une question cohérente avec le lieu installé, entrer dans une situation déjà existante."}},{"id":"1d68d592-2e98-4dcc-8b50-9d809c04087b","type":"exercise","status":"planned","durationSec":870,"locks":{},"recordedFiles":[],"exercise":{"name":"Décor puis question — celui qui entre demande","desc":"Même dispositif, mais c'est le jouteur qui monte sur scène une fois le décor installé qui pose la question à contexte. Objectifs : lire le décor planté par l'autre et s'en emparer, arriver avec une intention plutôt qu'attendre qu'on nous donne un rôle. Variante plus exigeante que la précédente."}},{"id":"61a759bc-072c-4b84-82dd-4b6115a5c47a","type":"exercise","status":"planned","durationSec":870,"locks":{},"recordedFiles":[],"exercise":{"name":"Simulation d'impro mixte","desc":"Impros mixtes à 2 jouteurs, services autorisés. Titres : « La dernière fraise de la saison » et « Tableau féerique / imaginaire ». Objectifs : réinvestir en conditions de match tout ce qui a été travaillé (démarrer vite, charger la première réplique, s'appuyer sur le partenaire). Les deux titres ouvrent des registres opposés : l'un concret et nostalgique, l'autre onirique et visuel."}}],"cursor":0,"journal":[],"matchDate":"2026-09-16"}$json$::jsonb)
    ) as x(title, data)
   where not exists (select 1 from public.shared_resources r
                      where r.owner_id = v_owner and r.resource_type = 'entrainement' and r.title = x.title);
  get diagnostics v_ajouts = row_count;
  raise notice '% coaching(s) ajoute(s) au compte', v_ajouts;
end $seed$;

